import {STAGES,TOOLS,MACHINES,SKILLS,freshState,manualRate,autoRate,machineCost,skillCost,tick,buyTool,buyMachine,buySkill,placeMachine,pendingMachines,advance,prestige,loadState,volume,money} from './game.js';
