const $=s=>nodes.get(s)||document.querySelector(s),SAVE='get-rid-of-the-ocean-v1';
let state=freshState(),storageAvailable=true,offlineRemoved=0;
try{const saved=localStorage.getItem(SAVE);if(saved){const loaded=loadState(saved);if(loaded){state=loaded;offlineRemoved=tick(state,Math.max(0,Math.min(3600,(Date.now()-state.savedAt)/1000)),false);}}}catch{storageAvailable=false;}
let settings=defaultSettings();try{settings=loadSettings(localStorage.getItem('lastdrop-settings-v1'));}catch{}
