let placement=null;
let holding=false,modalType=null,paused=false,completedShown=false,destination=null,near={nearWater:true,store:null,destinationDistance:0},lastFrame=performance.now(),uiTime=0,saveTime=0,gainTime=0,gainAmount=0,soundOn=false,audio=null,toastTimer=null,lastFocus=null,lastRaf=lastFrame,lastHiss=-1;
function save(){state.savedAt=Date.now();try{localStorage.setItem(SAVE,JSON.stringify(state));$('#save-status').textContent='● autosaved';}catch{storageAvailable=false;$('#save-status').textContent='save unavailable';}}
let saveQueued=false;
function queueSave(){if(saveQueued)return;saveQueued=true;const run=()=>{saveQueued=false;save();};if(globalThis.requestIdleCallback)requestIdleCallback(run,{timeout:2000});else setTimeout(run,100);}

function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function chime(freq=620){if(!soundOn||!audio)return;const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.setValueAtTime(freq,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(freq*1.4,audio.currentTime+.12);gain.gain.setValueAtTime(.045,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.25);osc.connect(gain).connect(audio.destination);osc.start();osc.stop(audio.currentTime+.26);}
function initAudio(){if(!audio){audio=new AudioContext();const buffer=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.2;const noise=audio.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1300;const gain=audio.createGain();gain.gain.value=0;noise.connect(filter).connect(gain).connect(audio.destination);noise.start();audio.hiss=gain;}audio.resume();}
function setDestination(id){destination=id;world.setDestination(id);$('#waypoint').classList.remove('hidden');toast(id==='trophies'?'Follow the marker to your empty-container trophy yard.':id==='water'?'Follow the orange marker back to the water.':`Walk to ${id==='tools'?'the Tool Shack':id==='skills'?'the Skill Lab':'Automation Co.'} and press E.`);}


function cancelPlacement(){placement=null;holding=false;world.previewPlacement(null);$('#placement-panel').classList.add('hidden');}
function beginPlacement(type=null){if(type===null)type=state.machines.findIndex((n,i)=>n>state.placedMachines[i]);if(type<0||state.machines[type]<=state.placedMachines[type]){toast('No packed machines to place.');return;}
 placement=type;holding=false;world.releaseLook();world.enableLook();world.previewPlacement(type);world.setDestination('water');destination='water';$('#waypoint').classList.remove('hidden');$('#placement-panel').classList.remove('hidden');$('#placement-title').textContent='PLACE '+MACHINES[type].name.toUpperCase();$('#placement-instructions').textContent='Walk to the water. The green outline snaps UNDER the source. Press '+keyLabel(settings.bindings.interact)+' or click INSTALL.';toast('Your '+MACHINES[type].name+' is packed. Bring it to the water and install it underneath.');renderHud();}
function confirmPlacement(){if(placement===null)return;if(!world.nearWater()){toast('Move closer to the water. Follow the orange marker.');return;}const type=placement;const before=state.remaining;if(!placeMachine(state,type)){cancelPlacement();return;}cancelPlacement();world.setMachines(state.placedMachines);world.setProgress(state.trophies);world.commissioning();save();chime(800);toast(MACHINES[type].name+' fired up! '+volume(before-state.remaining)+' removed by its startup surge. Follow the glowing pipes to see it work.');renderHud();}
$('#place-automation').onclick=()=>{if(modalType)closeModal();beginPlacement();};$('#confirm-placement').onclick=confirmPlacement;$('#cancel-placement').onclick=cancelPlacement;
function setHudText(selector,value){const node=$(selector);const text=String(value);if(node.textContent!==text)node.textContent=text;}
function renderHud(){
 document.body.classList.toggle('commissioning',near.commissioning>0);const packed=pendingMachines(state);$('#place-automation').classList.toggle('hidden',packed===0);setHudText('#place-automation','PLACE AUTOMATION ('+packed+')');
 const s=STAGES[state.stage],pct=state.remaining/s.capacity*100,manual=manualRate(state),automatic=autoRate(state),working=placement===null&&holding&&near.nearWater&&!state.complete&&!modalType&&!paused;
 setHudText('#stage-number',`0${state.stage+1} / 06`);setHudText('#stage-tag',s.tag);setHudText('#stage-name',s.name);setHudText('#stage-story',s.story);setHudText('#water-remaining',volume(state.remaining));setHudText('#water-percent',`${pct.toFixed(1)}% full`);setHudText('#level-removed',`${(100-pct).toFixed(1)}% REMOVED`);setHudText('#level-caption',state.complete?'Empty! Explore the dry bed, or press your interact key for the next stage.':state.stage>=3&&pct<85?(near.exposedArea>0?Math.round(near.exposedArea).toLocaleString()+' m² of shore exposed · walk down and explore':'Pool steps are emerging · walk down as they dry'):near.nearWater?'Orange line = original level · white line = water now':'Find the water to see its level');setHudText('#heat-state',near.heat>.1?'♨ HEATING THE WATER':automatic>0?'≈ AUTOMATION RUNNING':'≈ WATER LEVEL');$('#heat-state').classList.toggle('hot',near.heat>.1);const width=pct.toFixed(2)+'%';if($('#water-fill').style.width!==width)$('#water-fill').style.width=width;setHudText('#removed-stat',`${volume(s.capacity-state.remaining)} removed`);setHudText('#cash',money(state.cash));setHudText('#income',automatic>0?`${money(automatic/s.capacity*s.revenue*(1+state.skills[1]*.2))} / sec on autopilot`:'Every drop pays.');
 setHudText('#tool-name',TOOLS[state.tool].name);setHudText('#power',`${volume(working?manual:0)} / sec · ${working?'ON':'OFF'}`);$('#power').title=`Available tool power: ${volume(manual)} / sec`;setHudText('#auto-rate',`${volume((paused||state.complete?0:automatic)+(working?manual:0))} / sec`);const count=state.machines.reduce((a,b)=>a+b,0);setHudText('#machine-count',`Tool ${volume(working?manual:0)}/s · Auto ${volume(paused||state.complete?0:automatic)}/s`);
 document.body.classList.toggle('working',working);$('#work-button').classList.toggle('active',working);$('#work-button').disabled=!!modalType||paused||state.complete;setHudText('#action-label',state.complete?'BEAUTIFULLY EMPTY':TOOLS[state.tool].kind==='fire'?'HOLD TO EVAPORATE':TOOLS[state.tool].kind==='scoop'?'HOLD TO SCOOP':TOOLS[state.tool].kind==='solar'?'HOLD TO ERASE':'HOLD TO DRAIN');setHudText('#action-hint',near.nearWater?(working?'One less drop in the world. Keep going.':`Hold ${keyLabel(settings.bindings.work)} or left mouse while looking. Every drop pays.`):'Walk closer to the water to use your tool.');
 $('#interaction').classList.toggle('hidden',!near.store||!!modalType);if(near.store)setHudText('#interaction span',`Visit ${near.store==='tools'?'the Tool Shack':near.store==='skills'?'the Skill Lab':'Automation Co.'}`);
 if(destination){const names={water:'THE WATER',tools:'TOOL SHACK',skills:'SKILL LAB',automation:'AUTOMATION CO.',trophies:'TROPHY YARD'};setHudText('#waypoint',`↓ ${names[destination]} · ${near.destinationDistance} m · WASD to walk`);}
 if(placement!==null){setHudText('#action-label','INSTALL '+MACHINES[placement].name.toUpperCase());setHudText('#action-hint','Preview snaps underneath the water · '+keyLabel(settings.bindings.interact)+' to install · Esc to cancel');$('#confirm-placement').disabled=!near.nearWater;$('#interaction').classList.add('hidden');}
 $('#performance-overlay').classList.toggle('hidden',!settings.showFPS);if(settings.showFPS){const info=world.getPerformance(performance.now());setHudText('#performance-overlay',info.fps+' FPS · p95 '+info.p95+' ms · resolution '+info.resolution+'%');}
 if(!storageAvailable)setHudText('#save-status','save unavailable');
}
function openModal(type){cancelPlacement();document.body.classList.add('modal-open');bindingAction=null;world.releaseLook();holding=false;world.keys.clear();lastFocus=document.activeElement;modalType=type;$('#modal-backdrop').classList.remove('hidden');renderModal();$('#modal-close').focus();}
